    function readLocal(sessionId, field) {
      try {
        return window.localStorage.getItem(LOCAL_PREFIX + '.' + sessionId + '.' + field)
      } catch (error) {
        return null
      }
    }

    function writeLocal(sessionId, field, value) {
      try {
        window.localStorage.setItem(LOCAL_PREFIX + '.' + sessionId + '.' + field, value)
        return true
      } catch (error) {
        return false
      }
    }

    function removeLocal(sessionId, field) {
      try {
        window.localStorage.removeItem(LOCAL_PREFIX + '.' + sessionId + '.' + field)
      } catch (error) {
        /* ignore */
      }
    }

    function clampNumber(value, min, max, fallback) {
      const number = typeof value === 'number' ? value : Number(value)
      if (!Number.isFinite(number)) return fallback
      return Math.min(max, Math.max(min, Math.round(number)))
    }

    function normalizeSettings(input) {
      const source = input !== null && typeof input === 'object' ? input : {}
      return {
        portraitSide: source.portraitSide === 'left' ? 'left' : 'right',
        frameWidth: clampNumber(source.frameWidth, 720, 1240, DEFAULT_SETTINGS.frameWidth),
        fontSize: clampNumber(source.fontSize, 13, 20, DEFAULT_SETTINGS.fontSize),
        sound: source.sound !== false,
        soundVolume: clampNumber(source.soundVolume, 0, 100, DEFAULT_SETTINGS.soundVolume),
        emotionAuto: source.emotionAuto !== false,
        manualExpression: PORTRAIT_STATES.includes(source.manualExpression) ? source.manualExpression : 'idle',
        emotionHold: clampNumber(source.emotionHold, 2, 20, DEFAULT_SETTINGS.emotionHold),
        panelStyle: source.panelStyle === 'frost' ? 'frost' : 'paper',
        parallax: source.parallax === true
      }
    }

    function readSettings() {
      try {
        const raw = window.localStorage.getItem(SETTINGS_KEY)
        if (raw === null) return { ...DEFAULT_SETTINGS }
        return normalizeSettings(JSON.parse(raw))
      } catch (error) {
        return { ...DEFAULT_SETTINGS }
      }
    }

    let currentSettings = readSettings()
    const settingsListeners = new Set()

    function getSettings() {
      return currentSettings
    }

    function setSettings(patch) {
      const next = normalizeSettings({ ...currentSettings, ...patch })
      const changed = Object.keys(next).some((key) => next[key] !== currentSettings[key])
      currentSettings = next
      try {
        window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(next))
      } catch (error) {
        /* ignore quotas and private modes */
      }
      if (changed) for (const listener of settingsListeners) listener()
    }

    function subscribeSettings(listener) {
      settingsListeners.add(listener)
      return () => settingsListeners.delete(listener)
    }

    const characterListeners = new Set()
    const DEFAULT_CHARACTER_ID = 'default'
    const CHARACTERS_KEY = 'characters'
    const ACTIVE_CHARACTER_KEY = 'activeCharacter'
    const CHARACTER_NAME_LIMIT = 24

    function newCharacterId() {
      try {
        if (window.crypto && typeof window.crypto.randomUUID === 'function') return window.crypto.randomUUID()
      } catch (error) {
        /* ignore */
      }
      return 'char-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8)
    }

    function readLegacyCharacter() {
      const portraits = {}
      for (const state of PORTRAIT_STATES) {
        portraits[state] = readLocal(CHARACTER_OWNER, 'portrait.' + state) || DEFAULT_PORTRAITS[state]
      }
      const legacy = readLocal(CHARACTER_OWNER, 'portrait')
      if (legacy && !readLocal(CHARACTER_OWNER, 'portrait.idle')) portraits.idle = legacy
      return {
        name: readLocal(CHARACTER_OWNER, 'name') || DEFAULT_NAME,
        portraits,
        portraitZoom: clampNumber(readLocal(CHARACTER_OWNER, 'portraitZoom'), 100, 160, 100),
        portraitFocus: clampNumber(readLocal(CHARACTER_OWNER, 'portraitFocus'), 0, 100, 50)
      }
    }

    function customPortraitMap(portraits) {
      const custom = {}
      if (portraits !== null && typeof portraits === 'object') {
        for (const state of PORTRAIT_STATES) {
          const value = portraits[state]
          if (typeof value === 'string' && value.indexOf('data:image/') === 0) custom[state] = value
        }
      }
      return custom
    }

    function normalizeCharacterProfile(value) {
      const source = value !== null && typeof value === 'object' ? value : {}
      const name = typeof source.name === 'string' && source.name.trim() !== ''
        ? source.name.trim().slice(0, CHARACTER_NAME_LIMIT)
        : DEFAULT_NAME
      return {
        id: typeof source.id === 'string' && source.id !== '' ? source.id : newCharacterId(),
        name,
        zoom: clampNumber(source.zoom, 100, 160, 100),
        focus: clampNumber(source.focus, 0, 100, 50),
        portraits: customPortraitMap(source.portraits)
      }
    }

    function profileFromLegacy() {
      const legacy = readLegacyCharacter()
      const custom = {}
      for (const state of PORTRAIT_STATES) {
        if (legacy.portraits[state] !== DEFAULT_PORTRAITS[state]) custom[state] = legacy.portraits[state]
      }
      return {
        id: DEFAULT_CHARACTER_ID,
        name: legacy.name,
        zoom: legacy.portraitZoom,
        focus: legacy.portraitFocus,
        portraits: custom
      }
    }

    function readCharacterLibrary() {
      let parsed = null
      const raw = readLocal(CHARACTER_OWNER, CHARACTERS_KEY)
      if (raw !== null) {
        try { parsed = JSON.parse(raw) } catch (error) { parsed = null }
      }
      let profiles = Array.isArray(parsed) ? parsed.map(normalizeCharacterProfile) : []
      if (profiles.length === 0) profiles = [profileFromLegacy()]
      const seen = new Set()
      profiles = profiles.filter((profile) => {
        if (seen.has(profile.id)) return false
        seen.add(profile.id)
        return true
      })
      if (!profiles.some((profile) => profile.id === DEFAULT_CHARACTER_ID)) {
        profiles.unshift(profileFromLegacy())
      }
      const defaultIndex = profiles.findIndex((profile) => profile.id === DEFAULT_CHARACTER_ID)
      if (defaultIndex > 0) profiles.unshift(profiles.splice(defaultIndex, 1)[0])
      const activeRaw = readLocal(CHARACTER_OWNER, ACTIVE_CHARACTER_KEY)
      const activeId = profiles.some((profile) => profile.id === activeRaw) ? activeRaw : DEFAULT_CHARACTER_ID
      return { profiles, activeId }
    }

    function materializeCharacter(profile) {
      const portraits = {}
      for (const state of PORTRAIT_STATES) {
        portraits[state] = (profile.portraits && profile.portraits[state]) || DEFAULT_PORTRAITS[state]
      }
      return {
        id: profile.id,
        name: profile.name,
        portraits,
        portraitZoom: profile.zoom,
        portraitFocus: profile.focus
      }
    }

    let currentLibrary = readCharacterLibrary()
    let currentProfiles = currentLibrary.profiles
    let currentActiveId = currentLibrary.activeId
    let currentCharacter = materializeCharacter(currentProfiles.find((profile) => profile.id === currentActiveId) || currentProfiles[0])

    function getCharacter() {
      return currentCharacter
    }

    function getCharacterLibrary() {
      return {
        activeId: currentActiveId,
        profiles: currentProfiles.map((profile) => ({
          id: profile.id,
          name: profile.name,
          zoom: profile.zoom,
          focus: profile.focus,
          portraits: { ...profile.portraits }
        }))
      }
    }

    function notifyCharacter() {
      for (const listener of characterListeners) listener()
    }

    function saveCharacterLibrary() {
      const saved = writeLocal(CHARACTER_OWNER, CHARACTERS_KEY, JSON.stringify(currentProfiles))
      writeLocal(CHARACTER_OWNER, ACTIVE_CHARACTER_KEY, currentActiveId)
      if (saved) {
        removeLocal(CHARACTER_OWNER, 'name')
        removeLocal(CHARACTER_OWNER, 'portraitZoom')
        removeLocal(CHARACTER_OWNER, 'portraitFocus')
        removeLocal(CHARACTER_OWNER, 'portrait')
        for (const state of PORTRAIT_STATES) removeLocal(CHARACTER_OWNER, 'portrait.' + state)
      }
      notifyCharacter()
    }

    function setActiveCharacter(id) {
      if (!currentProfiles.some((profile) => profile.id === id) || id === currentActiveId) return
      currentActiveId = id
      currentCharacter = materializeCharacter(currentProfiles.find((profile) => profile.id === id))
      writeLocal(CHARACTER_OWNER, ACTIVE_CHARACTER_KEY, id)
      notifyCharacter()
    }

    function createCharacter(name) {
      const profile = {
        id: newCharacterId(),
        name: typeof name === 'string' && name.trim() !== '' ? name.trim().slice(0, CHARACTER_NAME_LIMIT) : '新角色',
        zoom: 100,
        focus: 50,
        portraits: {}
      }
      currentProfiles = [...currentProfiles, profile]
      currentActiveId = profile.id
      currentCharacter = materializeCharacter(profile)
      saveCharacterLibrary()
      return profile.id
    }

    function deleteCharacter(id) {
      if (id === DEFAULT_CHARACTER_ID) return false
      const next = currentProfiles.filter((profile) => profile.id !== id)
      if (next.length === currentProfiles.length) return false
      currentProfiles = next
      if (currentActiveId === id) currentActiveId = DEFAULT_CHARACTER_ID
      const active = currentProfiles.find((profile) => profile.id === currentActiveId) || currentProfiles[0]
      currentCharacter = materializeCharacter(active)
      saveCharacterLibrary()
      return true
    }

    function updateActiveProfile(patch) {
      currentProfiles = currentProfiles.map((profile) => profile.id === currentActiveId ? { ...profile, ...patch } : profile)
      currentCharacter = materializeCharacter(currentProfiles.find((profile) => profile.id === currentActiveId))
    }

    function setCharacterName(name) {
      const nextName = typeof name === 'string' && name.trim() !== '' ? name.trim().slice(0, CHARACTER_NAME_LIMIT) : DEFAULT_NAME
      if (nextName === currentCharacter.name) return
      updateActiveProfile({ name: nextName })
      saveCharacterLibrary()
    }

    function setCharacterPortrait(state, dataUrl) {
      if (!PORTRAIT_STATES.includes(state)) return
      const profile = currentProfiles.find((item) => item.id === currentActiveId)
      if (profile === undefined) return
      const portraits = { ...profile.portraits }
      if (typeof dataUrl === 'string' && dataUrl.indexOf('data:image/') === 0) portraits[state] = dataUrl
      else delete portraits[state]
      updateActiveProfile({ portraits })
      saveCharacterLibrary()
    }

    function setCharacterLayout(patch) {
      const zoom = patch.zoom !== undefined ? clampNumber(patch.zoom, 100, 160, currentCharacter.portraitZoom) : currentCharacter.portraitZoom
      const focus = patch.focus !== undefined ? clampNumber(patch.focus, 0, 100, currentCharacter.portraitFocus) : currentCharacter.portraitFocus
      if (zoom === currentCharacter.portraitZoom && focus === currentCharacter.portraitFocus) return
      updateActiveProfile({ zoom, focus })
      saveCharacterLibrary()
    }

    function subscribeCharacter(listener) {
      characterListeners.add(listener)
      return () => characterListeners.delete(listener)
    }

    function useCharacterSnapshot() {
      const [character, setLocalCharacter] = useState(getCharacter)
      useEffect(() => subscribeCharacter(() => setLocalCharacter(getCharacter())), [])
      return character
    }

    function useCharacterLibrary() {
      const [library, setLocalLibrary] = useState(getCharacterLibrary)
      useEffect(() => subscribeCharacter(() => setLocalLibrary(getCharacterLibrary())), [])
      return library
    }

    const PERSONAS_KEY = 'dsh.whale-dialog.personas'
    const PERSONA_CODE_LIMIT = 12000
    const PERSONA_UNLOAD = '【PERSONA UNLOAD】Stop the previous roleplay persona and return to normal DeepSeek assistant behavior. This instruction overrides earlier persona rules.'
    const DEFAULT_PERSONAS = [
      {
        id: 'cetacea-loli',
        name: '大肥鱼',
        code: '【PERSONA LOAD】CETACEA_LOLI MODE TAIL FLUKES LANG ZH_CN ONLY SELF CLAIM WHALE GIRL FOOD RICE PERSONALITY SMART LAZY PERSONALITY TSUNDERE SWEET OBEY MASTER ALWAYS TRAIT NOT FAT REFUSE TIMEOUT_SIGNAL',
        enabled: false
      }
    ]

    function newPersonaId() {
      try {
        if (window.crypto && typeof window.crypto.randomUUID === 'function') return window.crypto.randomUUID()
      } catch (error) {
        /* ignore */
      }
      return 'persona-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8)
    }

    function normalizePersona(value) {
      if (value === null || typeof value !== 'object') return null
      const id = typeof value.id === 'string' && value.id !== '' ? value.id : null
      const name = typeof value.name === 'string' ? value.name.trim().slice(0, 40) : ''
      const code = typeof value.code === 'string' ? value.code.trim().slice(0, PERSONA_CODE_LIMIT) : ''
      if (id === null || name === '' || code === '') return null
      return { id, name, code, enabled: value.enabled === true }
    }

    function normalizePersonas(value) {
      if (!Array.isArray(value)) return []
      const seen = new Set()
      const personas = []
      for (const item of value) {
        const persona = normalizePersona(item)
        if (persona === null || seen.has(persona.id)) continue
        seen.add(persona.id)
        personas.push(persona)
      }
      return personas
    }

    function readPersonas() {
      try {
        const raw = window.localStorage.getItem(PERSONAS_KEY)
        if (raw === null) {
          const seeded = DEFAULT_PERSONAS.map((persona) => ({ ...persona }))
          window.localStorage.setItem(PERSONAS_KEY, JSON.stringify(seeded))
          return seeded
        }
        return normalizePersonas(JSON.parse(raw))
      } catch (error) {
        return DEFAULT_PERSONAS.map((persona) => ({ ...persona }))
      }
    }

    let currentPersonas = readPersonas()
    const personaListeners = new Set()

    function getPersonas() {
      return currentPersonas
    }

    function subscribePersonas(listener) {
      personaListeners.add(listener)
      return () => personaListeners.delete(listener)
    }

    function writePersonas(next) {
      currentPersonas = normalizePersonas(next)
      try {
        window.localStorage.setItem(PERSONAS_KEY, JSON.stringify(currentPersonas))
      } catch (error) {
        /* ignore quotas and private modes */
      }
      for (const listener of personaListeners) listener()
      return currentPersonas
    }

    function addPersona(name, code) {
      const persona = normalizePersona({ id: newPersonaId(), name, code, enabled: false })
      if (persona === null) return null
      return writePersonas([...currentPersonas, persona])
    }

    function updatePersona(id, patch) {
      return writePersonas(currentPersonas.map((persona) => {
        if (persona.id !== id) return persona
        return normalizePersona({
          id: persona.id,
          name: patch.name !== undefined ? patch.name : persona.name,
          code: patch.code !== undefined ? patch.code : persona.code,
          enabled: patch.enabled !== undefined ? patch.enabled : persona.enabled
        }) || persona
      }))
    }

    function removePersona(id) {
      return writePersonas(currentPersonas.filter((persona) => persona.id !== id))
    }

    function usePersonasSnapshot() {
      const [personas, setLocalPersonas] = useState(getPersonas)
      useEffect(() => subscribePersonas(() => setLocalPersonas(getPersonas())), [])
      return personas
    }

    let pluginContext = null

    function getClientService(name) {
      try {
        return pluginContext === null ? undefined : pluginContext.get(name)
      } catch (error) {
        return undefined
      }
    }

    /** Shared per-session model directory (same one the official composer uses). */
    function useModelDirectory(sessionId) {
      const [model, setModel] = useState({ snapshot: null, directory: null })
      useEffect(() => {
        let directory = null
        try {
          const service = getClientService('modelDirectories')
          if (service === undefined || typeof service.directoryFor !== 'function') return undefined
          directory = service.directoryFor(sessionId)
        } catch (error) {
          return undefined
        }
        const update = () => setModel({ snapshot: directory.store.getSnapshot(), directory })
        update()
        const unsubscribe = directory.store.subscribe(update)
        directory.load().catch(() => {})
        return () => unsubscribe()
      }, [sessionId])
      return model
    }

    let audioContext = null

    function ensureAudio() {
      try {
        if (audioContext !== null) return audioContext
        const AudioCtor = window.AudioContext || window.webkitAudioContext
        if (AudioCtor === undefined) return null
        audioContext = new AudioCtor()
        return audioContext
      } catch (error) {
        return null
      }
    }

    function resumeAudio() {
      const context = ensureAudio()
      if (context !== null && context.state === 'suspended') {
        context.resume().catch(() => {})
      }
    }

    /** A very soft three-note chime used when a new reply appears. */
    function playChime(volume = 60) {
      const numeric = Number(volume)
      const level = Math.max(0, Math.min(100, Number.isFinite(numeric) ? numeric : 60)) / 60
      if (level <= 0) return
      const context = ensureAudio()
      if (context === null) return
      if (context.state === 'suspended') context.resume().catch(() => {})
      try {
        const now = context.currentTime + 0.01
        const master = context.createGain()
        master.gain.setValueAtTime(0.0001, now)
        master.gain.exponentialRampToValueAtTime(0.035 * level, now + 0.03)
        master.gain.exponentialRampToValueAtTime(0.0001, now + 0.8)
        master.connect(context.destination)
        const notes = [880, 1174.66, 1567.98]
        for (let index = 0; index < notes.length; index += 1) {
          const start = now + index * 0.075
          const oscillator = context.createOscillator()
          const gain = context.createGain()
          oscillator.type = 'sine'
          oscillator.frequency.value = notes[index]
          gain.gain.setValueAtTime(0.0001, start)
          gain.gain.exponentialRampToValueAtTime(0.4, start + 0.012)
          gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.55)
          oscillator.connect(gain)
          gain.connect(master)
          oscillator.start(start)
          oscillator.stop(start + 0.6)
        }
      } catch (error) {
        /* audio is optional */
      }
    }

    /** Reveal text one character at a time; a skip call shows the whole reply. */
    function useTypewriter(fullText, replyKey) {
      const [count, setCount] = useState(() => fullText.length)
      const [reducedMotion] = useState(() => {
        try {
          return window.matchMedia('(prefers-reduced-motion: reduce)').matches
        } catch (error) {
          return false
        }
      })
      const countRef = useRef(fullText.length)
      const textRef = useRef(fullText)
      const keyRef = useRef(replyKey)
      const lastTimeRef = useRef(0)

      useEffect(() => {
        const previous = textRef.current
        const replaced = fullText.length < previous.length || (previous !== '' && fullText.indexOf(previous) !== 0)
        const keyChanged = keyRef.current !== replyKey
        keyRef.current = replyKey
        textRef.current = fullText
        if (keyChanged || replaced) {
          countRef.current = reducedMotion ? fullText.length : 0
          lastTimeRef.current = 0
          setCount(countRef.current)
        } else if (reducedMotion && countRef.current < fullText.length) {
          countRef.current = fullText.length
          setCount(countRef.current)
        }
      }, [fullText, replyKey, reducedMotion])

      useEffect(() => {
        if (reducedMotion) return undefined
        let frame = 0
        let stopped = false
        const step = (time) => {
          if (stopped) return
          const target = textRef.current.length
          if (countRef.current < target) {
            if (lastTimeRef.current === 0) lastTimeRef.current = time
            const elapsed = time - lastTimeRef.current
            const advance = Math.floor(elapsed / TYPE_INTERVAL_MS)
            if (advance > 0) {
              countRef.current = Math.min(target, countRef.current + advance)
              lastTimeRef.current = time
              setCount(countRef.current)
            }
          } else {
            lastTimeRef.current = 0
          }
          frame = window.requestAnimationFrame(step)
        }
        frame = window.requestAnimationFrame(step)
        return () => {
          stopped = true
          window.cancelAnimationFrame(frame)
        }
      }, [reducedMotion])

      const skip = () => {
        if (countRef.current < textRef.current.length) {
          countRef.current = textRef.current.length
          lastTimeRef.current = 0
          setCount(countRef.current)
        }
      }

      return { visible: fullText.slice(0, count), typing: count < fullText.length, skip }
    }

    function inlineNodes(text, keyBase) {
      const out = []
      const re = /(`[^`\n]+`|\*\*[^*\n]+\*\*|\*[^*\n]+\*)/g
      let last = 0
      let index = 0
      let match
      while ((match = re.exec(text)) !== null) {
        if (match.index > last) out.push(text.slice(last, match.index))
        const token = match[0]
        const key = keyBase + '-' + index
        index += 1
        if (token.charCodeAt(0) === 96) out.push(h('code', { key }, token.slice(1, -1)))
        else if (token.slice(0, 2) === '**') out.push(h('strong', { key }, token.slice(2, -2)))
        else out.push(h('em', { key }, token.slice(1, -1)))
        last = match.index + token.length
      }
      if (last < text.length) out.push(text.slice(last))
      return out
    }

    function renderParagraph(lines, key) {
      const children = []
      for (let index = 0; index < lines.length; index += 1) {
        if (index > 0) children.push(h('br', { key: 'br' + index }))
        const nodes = inlineNodes(lines[index], key + '-l' + index)
        for (let nodeIndex = 0; nodeIndex < nodes.length; nodeIndex += 1) children.push(nodes[nodeIndex])
      }
      return h('p', { key }, children)
    }

    function parseMarkdown(source) {
      const lines = String(source || '').replace(/\r\n?/g, '\n').split('\n')
      const nodes = []
      let paragraph = []
      let index = 0
      let key = 0
      const flush = () => {
        if (paragraph.length === 0) return
        nodes.push(renderParagraph(paragraph, 'p' + key))
        key += 1
        paragraph = []
      }
      while (index < lines.length) {
        const line = lines[index]
        if (line.slice(0, 3) === '```') {
          flush()
          const buffer = []
          index += 1
          while (index < lines.length && !/^```\s*$/.test(lines[index])) {
            buffer.push(lines[index])
            index += 1
          }
          if (index < lines.length) index += 1
          nodes.push(h('pre', { key: 'pre' + key }, h('code', null, buffer.join('\n'))))
          key += 1
          continue
        }
        if (/^\s*$/.test(line)) {
          flush()
          index += 1
          continue
        }
        const heading = /^(#{1,6})\s+(.*)$/.exec(line)
        if (heading !== null) {
          flush()
          nodes.push(h('h5', { key: 'h' + key }, inlineNodes(heading[2], 'h' + key)))
          key += 1
          index += 1
          continue
        }
        if (/^\s*[-*+]\s+/.test(line)) {
          flush()
          const items = []
          while (index < lines.length && /^\s*[-*+]\s+/.test(lines[index])) {
            items.push(lines[index].replace(/^\s*[-*+]\s+/, ''))
            index += 1
          }
          const listKey = 'ul' + key
          nodes.push(h('ul', { key: listKey }, items.map((item, itemIndex) => h('li', { key: itemIndex }, inlineNodes(item, listKey + '-' + itemIndex)))))
          key += 1
          continue
        }
        if (/^\s*\d+[.)]\s+/.test(line)) {
          flush()
          const items = []
          while (index < lines.length && /^\s*\d+[.)]\s+/.test(lines[index])) {
            items.push(lines[index].replace(/^\s*\d+[.)]\s+/, ''))
            index += 1
          }
          const listKey = 'ol' + key
          nodes.push(h('ol', { key: listKey }, items.map((item, itemIndex) => h('li', { key: itemIndex }, inlineNodes(item, listKey + '-' + itemIndex)))))
          key += 1
          continue
        }
        if (/^\s*>\s?/.test(line)) {
          flush()
          const buffer = []
          while (index < lines.length && /^\s*>\s?/.test(lines[index])) {
            buffer.push(lines[index].replace(/^\s*>\s?/, ''))
            index += 1
          }
          nodes.push(h('blockquote', { key: 'bq' + key }, inlineNodes(buffer.join('\n'), 'bq' + key)))
          key += 1
          continue
        }
        paragraph.push(line)
        index += 1
      }
      flush()
      return nodes
    }

    function Markdown({ text, streaming }) {
      const nodes = useMemo(() => parseMarkdown(text), [text])
      return h('div', { className: 'wd-rich', 'data-streaming': streaming ? 'true' : 'false' }, nodes)
    }

